/**
 * Activity-side suspension adapter for the node-red-agents Interaction v1
 * node ABI. Interaction plans may evaluate typed properties asynchronously,
 * so planning is async; the generic signal suspension carries its opaque
 * continuation back to a fresh resume Activity.
 */

"use strict";

function createInteractionSuspensionAdapter({ capture }) {
    async function plan(node, msg) {
        if (!node || node.type !== "interaction") {
            return undefined;
        }
        const continuation = await node.interaction.plan(msg);
        return { type: "signal", key: continuation.interactionId, continuation };
    }

    function resume(node, msg, resumeInput) {
        const routed = capture.routeSend(node, msg, () => {
            node.interaction.resume(resumeInput.continuation, msg, resumeInput.signal);
        });
        return { sends: routed.sends };
    }

    return { plan, resume };
}

module.exports = { createInteractionSuspensionAdapter };
